#Requires -Version 7.6
param([switch]$Emit,[switch]$Write)
. "$PSScriptRoot/Hexagon.Common.ps1"
$script:AuditedUpstream = @(@{'path'='ggml/src/ggml-hexagon/htp/hmx-mm-kernels-tiled.h';'sha256'='55e39f66cff4bde164e3ed3f8038aaea9f4b56d83c58546cfd8558111a5beb53';'role'='dequantize_tiled_weight_to_fp16_task_q2_0 (lines 788-821), core_dot_chunk_fp16 with HMX_STORE_AFTER_F16 to __fp16 *vtcm_output (lines 966-1040), transfer_output_chunk_threaded FP16-to-FP32 widening (lines 1143-1208)'},@{'path'='ggml/src/ggml-hexagon/htp/hvx-mm-kernels-tiled.h';'sha256'='89dbb3c7a2e4da170c657f47d3bce57376a1aad445e2bbd62814ca8bcb00dd6f';'role'='quantize_block_f32_q8_1_tiled_impl per-32 FP16 activation quantization (lines 7-135) and tiled_vec_dot_q2_0_32x1 per-64 qf32 accumulation (lines 1543-1575)'},@{'path'='ggml/src/ggml-hexagon/htp/matmul-ops.c';'sha256'='f7158e60056c2e67ce3c0d16d8cbe4cc4eac18ab012573393797d2';'role'='hmx_mm_2d_f32 double-buffered DMA/HVX/HMX chunk loop (lines 2816-2921), dequantize_tiled_weight_chunk_to_fp16_tiles (line 2382), transfer_output_chunk_threaded (line 2438)'},@{'path'='ggml/src/ggml-hexagon/htp/matmul-ops.h';'sha256'='e2afab4816382eb7b693aafdab6f937c35454889cb356b352436a79330ab0';'role'='htp_mm_hmx_compute_act_threads (line 318), htp_mm_hmx_compute_chunks (line 395), htp_mm_hmx_vtcm_layout_build (line 596), htp_mm_hmx_solve_2d_params (line 712)'},@{'path'='ggml/src/ggml-hexagon/htp/htp-ops.h';'sha256'='ce6c7d7c5ad5f9ad9eae4b096f3cedecd5f885b642213a5ea0c448cbb911fea0';'role'='htp_op_type opcode table (lines 47-105) and htp_mm_kernel_params ABI (lines 147-179)'},@{'path'='ggml/src/ggml-hexagon/htp/sum-rows-ops.c';'sha256'='cd40cd75786686e4fe93806616111c22f7c587b9e21a6bb43f8152ef023c85b5';'role'='HTP_OP_SUM_ROWS reduction along ne[0] rather than ne[1] plane rows (lines 1-215)'},@{'path'='ggml/src/ggml-hexagon/htp/main.c';'sha256'='184b777a7ba11f178c2cb5b1ced477cce0d9ba3083a65eb47edd15b6049a018b';'role'='set_hmx_power / HTP_POWER_MODE_BURST=7 (lines 426-439), htp_iface_start worker_pool creation with n_hvx threads (lines 494-684), handle_Execute batch loop (lines 1166-1277)'})
function Get-DspReductionAudit { return @{'hmxMinimumRowPredicate'=@{'source'='ggml/src/ggml-hexagon/htp-kparams.cpp::htp_matmul_is_hmx_eligible (line 640)';'constant'='HTP_MM_HMX_MIN_NROWS = 4';'predicate'='M > HTP_MM_HMX_MIN_NROWS';'consequence'='Activation bitplanes must be submitted with M = 8 rows (> 4), producing output tensor [ne0 = N = 17408, ne1 = M = 8].'};'sumRowsAxisMismatch'=@{'opcode'='HTP_OP_SUM_ROWS (27)';'source'='ggml/src/ggml-hexagon/htp/sum-rows-ops.c (lines 1-215)';'reducedDimension'='ne[0] (the 17408 weight-row dimension)';'preservedDimension'='ne[1] (the 8 bitplane rows)';'consequence'='HTP_OP_SUM_ROWS collapses [17408, 8] to [1, 8] (summing across the 17408 output neurons) instead of reducing across the 8 bitplanes to [17408, 1].'};'missingSignedWeightedPlaneFmaOpcode'=@{'requiredPlaneWeights'=@(1,2,4,8,16,32,64,-128);'requiredPer128BlockAccumulation'='f32::mul_add(d_pq2[b] * d_q8[b // 2], dot_b as f32, acc)';'secondMatmulM1Fallback'='A second OP_MUL_MAT reducing 8 planes to M = 1 row fails M > 4 and falls back to HVX Q8_1 dynamic quantization, altering integer plane values.';'scaleAddChainOverheadAndRounding'='Seven sequential HTP_OP_SCALE + HTP_OP_ADD passes over 17408 floats per K=128 block (280 extra DSP ops per projection) read/write 17408-element FP32 buffers 7 times and perform separate FP32 additions rather than PinnedSwift''s single integer reconstruction + per-128-block f32::mul_add.';'supportedBySignedV0100Package'=$false}} }
$script:HvxQuantizerReview = @{'kernelId'='HTP_MM_KERNEL_HVX_QUANT_ROW (6)';'activationQuantizer'='quantize_block_f32_q8_1_tiled_impl (per-32-element FP16 scale d and FP16 sum s)';'requiredSwiftQuantizer'='PinnedSwift Q8_K (per-256-element FP32 scale d and 16-element i16 sums)';'guardedK256Limitation'='Guarded K=256 uses 31 real lanes + 1 guard lane (+/-127) per 32-element Q8_1 block to force unit Q8_1 scale 1.0 over a single 128-weight PQ2_0 block; extending across multiple 128-weight blocks still cannot apply distinct per-128-block PQ2_0 scales or per-128-block f32::mul_add.'}
function Round-HexagonHalf([double]$Value) { return [float]([Half]::op_Explicit([float]$Value)) }
function Get-HmxChunks([long]$Rows,[long]$VtcmBudget,[int]$Threads) {
    Assert-Hexagon ($Rows -gt 0 -and $Rows % 32 -eq 0) 'rows must be a positive multiple of 32'
    Assert-Hexagon ($Threads -ge 1 -and $Threads -le 8) 'n_threads must be in 1..=8'
    $actThreads=[Math]::Min($Threads,4);$usable=$VtcmBudget-(5*2048+256)
    Assert-Hexagon ($usable -ge 32*296) 'vtcm_budget too small for one 32-column tile'
    $best=$null
    for ($columns=32;$columns -le [Math]::Min($Rows,[Math]::Floor($usable/296));$columns+=32) {
        $remaining=$usable-$columns*296;$mc=[Math]::Min([Math]::Floor([Math]::Floor($remaining/(256+$columns*2))/32)*32,32)
        if ($mc -eq 0) {continue}
        $blocks=[long][Math]::Ceiling($Rows/$columns);$waste=if ($Rows%$columns -eq 0) {0} else {$columns-$Rows%$columns}
        if ($null -eq $best -or $blocks -lt $best.blocks -or ($blocks -eq $best.blocks -and ($waste -lt $best.waste -or ($waste -eq $best.waste -and $columns -gt $best.columns)))) {$best=@{blocks=$blocks;waste=$waste;columns=$columns}}
    }
    Assert-Hexagon ($null -ne $best) 'no valid HMX chunk configuration found';$columns=$best.columns
    $weight=[long]([Math]::Ceiling(($columns/32*2*640)/2048)*2048);$output=[long]([Math]::Ceiling((32*$columns*2)/2048)*2048);$scratch=[long]([Math]::Ceiling(($columns*256)/2048)*2048)
    $group=$weight+$output+$scratch;$clamped=[Math]::Max($actThreads*1024,[Math]::Min($actThreads*32768,$group));$activation=[long]([Math]::Ceiling($clamped/128)*128);$size=2048+8192+[Math]::Max($group,$activation)
    Assert-Hexagon ($size -le $VtcmBudget) 'solved VTCM layout exceeds vtcm_budget';$chunks=[long][Math]::Ceiling($Rows/$columns)
    return @{rows=$Rows;vtcmBudgetBytes=$VtcmBudget;hvxThreads=$Threads;actThreads=$actThreads;nChunk=$columns;vtcmSizeBytes=$size;weightVtcmBytes=$weight;outputVtcmBytes=$output;scratchVtcmBytes=$scratch;activationTempVtcmBytes=$activation;chunksPerOperation=$chunks;chunksPer40OpProjection=40*$chunks;tailWasteRows=$(if ($Rows%$columns -eq 0) {0} else {$columns*$chunks-$Rows})}
}
function Get-KTilingCounterexamples {
    $d0=Get-HexagonHalf 0x3c01;$d1=Get-HexagonHalf 0x3787;$q8=[BitConverter]::UInt32BitsToSingle(0x3da00001)
    $factor0=[float]($d0*$q8);$factor1=[float]($d1*$q8)
    $acc0=[MathF]::FusedMultiplyAdd($factor0,[float]384,[float]0);$pinned=[MathF]::FusedMultiplyAdd($factor1,[float]-1664,$acc0)
    $pinnedBits=[BitConverter]::SingleToUInt32Bits($pinned).ToString('x8');Assert-Hexagon ($pinnedBits -ceq 'c1f90b01') 'PinnedSwift golden mismatch'
    $reconstructed=[float]0;$coefficients=@(1,2,4,8,16,32,64,-128)
    for ($bit=0;$bit -lt 8;$bit++) {
        $plane=Round-HexagonHalf (128.0*($d0*((3 -shr $bit) -band 1))+128.0*($d1*((243 -shr $bit) -band 1)))
        $reconstructed=[float]([double]$reconstructed+[double]$coefficients[$bit]*[double]$plane*[double]$q8)
    }
    $bakedBits=[BitConverter]::SingleToUInt32Bits($reconstructed).ToString('x8');$rounded=Round-HexagonHalf 2049
    Assert-Hexagon ($rounded -ne 2049) 'IEEE-754 binary16 cannot represent 2049 exactly'
    return @{singleBlockK128ExactRange=@{k=128;minPlaneDot=-128;maxPlaneDot=256;fp16ExactIntegerCeiling=2048;allPlaneDotsExactInFp16=$true};twoBlockK256DistinctScalesCounterexample=@{k=256;block0ScaleHalfBits='3c01';block1ScaleHalfBits='3787';q8kSuperblockScaleF32Bits='3da00001';block0IntegerDot=384;block1IntegerDot=-1664;unweightedCombinedIntegerDot=-1280;unweightedScaleFactorable=$false;pinnedSwiftPer128BlockFmaF32Bits=$pinnedBits;hmxBakedScaleK256Fp16StoreF32Bits=$bakedBits;matchesPinnedSwiftBitwise=($pinnedBits -ceq $bakedBits)};multiBlockFp16IntegerTruncation=@{hmxOutputStoreMacro='HMX_STORE_AFTER_F16 (__fp16 *vtcm_output at hmx-mm-kernels-tiled.h:987,1034)';fp16SignificandBits=11;firstInexactPositiveIntegerInFp16=2049;fp16RoundedValueFor2049=[int]$rounded;maxUnweightedPlaneDotAtK5120=10240}}
}
function Get-KTilingAudit {
    $candidate='config/hexagon-signed-q2-candidate.lock.json';$packedPath='tools/hexagon/packed-sources.json';$revision='19cce6919992fdffd92e0ac152caaf1e2b8f254e'
    $lock=ConvertFrom-HexagonJson (Read-HexagonSource $candidate);Assert-Hexagon ($lock.candidate.gitlink.commit -ceq $revision) 'candidate lock ggml revision changed'
    $packed=ConvertFrom-HexagonJson (Read-HexagonSource $packedPath);Assert-Hexagon ($packed.independentNativeCapture.pq2Dot.expectedF32Bits -ceq 'c1f90b01') 'packed-sources golden pq2Dot changed'
    $legacy=Get-HmxChunks 17408 65536 1;$optimized=Get-HmxChunks 17408 2097152 8;$small32=Get-HmxChunks 32 2097152 8;$small64=Get-HmxChunks 64 2097152 8
    Assert-Hexagon ($legacy.nChunk -eq 128 -and $legacy.vtcmSizeBytes -eq 57344 -and $legacy.chunksPerOperation -eq 136) 'legacy 64 KiB 1-HVX solver derivation changed'
    Assert-Hexagon ($optimized.nChunk -eq 4352 -and $optimized.vtcmSizeBytes -eq 1576960 -and $optimized.chunksPerOperation -eq 4) 'optimized 2 MiB 8-HVX solver derivation changed'
    Assert-Hexagon ($small32.nChunk -eq 32 -and $small32.vtcmSizeBytes -eq 22528 -and $small64.nChunk -eq 64 -and $small64.vtcmSizeBytes -eq 34816) 'small-row solver derivation changed'
    $counterexamples=Get-KTilingCounterexamples;Assert-Hexagon (-not $counterexamples.twoBlockK256DistinctScalesCounterexample.matchesPinnedSwiftBitwise) 'K=256 baked-scale counterexample unexpectedly matched PinnedSwift'
    $legacy.powerMode=4;$legacy.powerModeName='HTP_POWER_MODE_BALANCED';$legacy.divNActThreads=@{mul=1;add=0;shift=0}
    $optimized.powerMode=7;$optimized.powerModeName='HTP_POWER_MODE_BURST';$optimized.divNActThreads=@{mul=1;add=0;shift=2};$optimized.chunkBarrierReductionFactor=$legacy.chunksPerOperation/$optimized.chunksPerOperation;$optimized.hvxWorkerParallelismFactor=$optimized.hvxThreads/$legacy.hvxThreads;$optimized.actWorkerParallelismFactor=$optimized.actThreads/$legacy.actThreads;$optimized.smallRowControls=@{rows32=@{nChunk=$small32.nChunk;vtcmSizeBytes=$small32.vtcmSizeBytes};rows64=@{nChunk=$small64.nChunk;vtcmSizeBytes=$small64.vtcmSizeBytes}}
    $sources=@($candidate,$packedPath,'tools/hexagon/hmx_projection.rs','tools/hexagon/q2_integer.rs')
    return @{schemaVersion=1;kind='static-v0100-htp-k-tiling-reduction-and-hvx-vtcm-solver-audit';ggmlRevision=$revision;sourceIdentityEncoding='UTF8-with-LF-newlines';sources=@($sources | ForEach-Object {@{path=$_;sha256=(Get-HexagonHash (Read-HexagonSource $_))}});upstreamHtpSourcesAudited=$script:AuditedUpstream;multiBlockKTilingAudit=@{supportedWithPinnedSwiftBitwiseParity=$false;hmx2dKernel=$counterexamples;hvxQuantRowKernel=$script:HvxQuantizerReview};dspPlaneAndScaleReductionAudit=(Get-DspReductionAudit);signedBinaryExecutionOptimizations=@{hardwareCapabilitiesOnSnapdragonX2V81=@{hvx128Contexts=8;vtcmPageBytes=8388608;hmxUnits=1};previousSessionAndSolverConfig=$legacy;optimizedSessionAndSolverConfig=$optimized};newOwnerDeviceExecutionMilliseconds=0;deviceOpened=$false;modelLoaded=$false;profileEligible=$false}
}
if ($MyInvocation.InvocationName -ne '.') {
    Assert-Hexagon (-not ($Emit -and $Write)) 'emit and write are mutually exclusive';$expected=Get-KTilingAudit;$path=Join-Path $script:HexagonRoot 'docs/evidence/hexagon-k-tiling-and-reduction-audit.json'
    if ($Write) {Write-HexagonJson $path $expected} elseif ($Emit) {$expected | ConvertTo-Json -Depth 64} else {Assert-Hexagon (Test-HexagonEqual (Read-HexagonJson $path) $expected) 'retained K-tiling and reduction audit differs from source-derived report';Write-Output 'Static v0.10.0 HTP K-tiling, reduction, and 8-HVX/2MiB-VTCM solver audit verified.'}
}
